{
  "proposed_action": "RUN_SCRIPT",
  "parameters": {
    "script_name": "titanic_groupcv_baseline_v1",
    "language": "python",
    "purpose": "Establish group-disjoint CV baseline for hist_gbdt and penalized_linear families on Titanic with engineered features; report per-fold and mean accuracy.",
    "seed": 42,
    "families": ["hist_gbdt", "penalized_linear"],
    "cv": {
      "kind": "group_kfold",
      "n_splits": 5,
      "group_column": "frozen_family_ticket_mapping",
      "shuffle": true,
      "seed": 42
    },
    "feature_engineering": [
      "Title extracted from Name (rare titles bucketed to 'Rare')",
      "FamilySize = SibSp + Parch + 1",
      "IsAlone = (FamilySize == 1)",
      "TicketPrefix = leading alpha token of Ticket, else 'NONE'",
      "CabinDeck = first char of Cabin, else 'U'",
      "Age imputed by median within (Sex, Pclass); AgeMissing flag",
      "Fare log1p transform; FareMissing flag",
      "Embarked mode-imputed",
      "One-hot encode Sex, Embarked, Title, TicketPrefix, CabinDeck; ordinal Pclass"
    ],
    "models": {
      "hist_gbdt": {
        "estimator": "HistGradientBoostingClassifier",
        "params": {"max_iter": 300, "learning_rate": 0.05, "max_depth": null, "max_leaf_nodes": 31, "l2_regularization": 1.0, "early_stopping": true, "random_state": 42}
      },
      "penalized_linear": {
        "estimator": "LogisticRegression",
        "params": {"penalty": "l2", "C": 1.0, "solver": "liblinear", "max_iter": 2000, "random_state": 42}
      }
    },
    "preprocessing": "ColumnTransformer with StandardScaler on numeric, OneHotEncoder(handle_unknown='ignore') on categorical; fit inside each CV fold to avoid leakage.",
    "outputs": [
      "per_fold_accuracy per family",
      "mean_accuracy and std per family",
      "confusion matrix per family (aggregated OOF)",
      "feature importance / coefficient summary"
    ],
    "notes": "Group column 'frozen_family_ticket_mapping' is assumed present in the dataset; if absent, derive from Ticket+FamilySize grouping and log a warning. Do not touch final holdout."
  }
}
